import{_ as n,b as e,c as a,g as i}from"./chunks/framework.86O3EbG5.js";const g=JSON.parse('{"title":"楚汉 · 象棋","description":"","frontmatter":{},"headers":[],"relativePath":"public/xiangqi/README.md","filePath":"public/xiangqi/README.md"}'),t={name:"public/xiangqi/README.md"};function p(l,s,o,d,c,r){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="楚汉-·-象棋" tabindex="-1">楚汉 · 象棋</h1><p>浏览器里的工笔重彩中国象棋。棋子是程序化的古代军士，不是字面圆片。规则、搜索、材质、声音全部手写。</p><h2 id="怎么玩" tabindex="-1">怎么玩</h2><p>站点把 <code>docs/public/</code> 发到根路径，打开 <strong><code>/xiangqi/</code></strong>。首页「中国象棋」会跳转到此。本地在仓库根目录 <code>npm start</code>，然后访问同一路径。</p><h2 id="架构" tabindex="-1">架构</h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>core/       棋盘常量、矿物色板、格点坐标</span></span>
<span class="line"><span>engine/     规则、Zobrist、评估、Alpha-beta、开局库、Worker</span></span>
<span class="line"><span>render/     工笔 Shader、描边、Sobel、程序纹理</span></span>
<span class="line"><span>units/      共享骨架、硬边几何、汉楚形制、动画、IK、三拍吃子</span></span>
<span class="line"><span>world/      木案棋盘、千里江山、弹簧镜头</span></span>
<span class="line"><span>ui/         绢色 HUD、棋谱、复盘、Web Audio、存档</span></span>
<span class="line"><span>game.js     对局编排</span></span></code></pre></div><p>Three.js 只从 CDN 引入 <code>three@0.170.0</code>。不下载网格、贴图、字体、音频、棋库文件。</p><h2 id="规则测试" tabindex="-1">规则测试</h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#6F42C1;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#032F62;"> docs/public/xiangqi/engine/tests.js</span></span></code></pre></div><p>覆盖飞将、蹩马腿、塞象眼、炮架、过河、困毙、将死、开局 perft。长将与六十回合在 <code>engine/repetition.js</code>，由对局层调用。</p><h2 id="剪影模式" tabindex="-1">剪影模式</h2><p>对局中点「剪影」，或 URL 加 <code>?silhouette=1</code>。用来核验兵种能不能只靠轮廓认出来。</p><h2 id="质量自评-诚实" tabindex="-1">质量自评（诚实）</h2><ul><li><strong>规则引擎</strong>：开局 perft 红 44 / 两层 1920，测试套件应全绿。困毙按负、长将、六十回合已接线。弱社难度是受限深度 + 有界噪声，并剔除大漏着；不是随机送车。</li><li><strong>工笔管线</strong>：4 档量化 ramp、墨线倒壳、Sobel 内轮廓、阴影绢纹都在。级联阴影改成单盏紧正交光，避免多 cascade 把色带洗灰。</li><li><strong>角色</strong>：14 种模板（七兵种 × 汉楚），共享骨架蒙皮。汉是朱砂雉尾，楚是墨甲高冠戈，不是换色。马/象的蹄步绑定大约六成——腿贴马腹有 IK 约束，但马身本身不是全骨骼四蹄 IK，侧向走时仍可能读出一点滑。</li><li><strong>吃子</strong>：三拍时间是 0.73 / 0.17 / 0.91，炮走抛物线石弹，颜料是硬边薄片不是雾。接触锁定（手不离兵、脚不穿地）靠挂接 + IK，不是影像级动作捕捉。</li><li><strong>捕获工具链</strong>：没有 Playwright 无头管线（避免给博客仓库加一套浏览器依赖）。用剪影按钮和浏览器截帧代替。动画重量只能在实机运动里看。</li><li><strong>HUD</strong>：竖排棋谱、评估墨条、印章按钮是 DOM，做成绢色而不是默认灰按钮；被吃子会停到棋盘两侧倒下，同时也在边缘列出文字。</li></ul>`,14)])])}const b=n(t,[["render",p]]);export{g as __pageData,b as default};
